class Signal {
  std::mutex m_; std::vector<std::function<void(const Price&)>> slots_;
public:
  void publish(const Price& p) {
    std::vector<std::function<void(const Price&)>> snapshot;
    { std::lock_guard<std::mutex> lk(m_); snapshot = slots_; }
    for (auto& s : snapshot) s(p);   // outside the lock
  }
};
